import fs from "node:fs";
import path from "node:path";

import { SAMPLES, USERS, expect, test, uniqueName } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;
type Kind = (typeof KINDS)[number];

/** Locate a sample file for a document kind by name, e.g. "w9.pdf", "insurance-certificate.pdf". */
function sampleFor(kind: Kind): string {
  const files = fs.readdirSync(SAMPLES);
  const needles: Record<Kind, string[]> = {
    w9: ["w9", "w-9"],
    insurance_certificate: ["insurance", "coi", "certificate"],
    contract: ["contract", "agreement", "msa"],
  };
  const match = files.find((f) => needles[kind].some((n) => f.toLowerCase().includes(n)));
  if (!match) throw new Error(`No sample file for kind "${kind}" in ${SAMPLES}: ${files.join(", ")}`);
  return path.join(SAMPLES, match);
}

function mimeTypeFor(file: string): string {
  const ext = path.extname(file).toLowerCase();
  if (ext === ".pdf") return "application/pdf";
  if (ext === ".png") return "image/png";
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".txt") return "text/plain";
  return "application/octet-stream";
}

test.describe("Review vendors", () => {
  test(
    "Submit a vendor with all documents extracted",
    { tag: "@REV-01" },
    async ({ apiAs }) => {
      test.setTimeout(120_000);

      // Given I am signed in as member@northwind.test
      const member = await apiAs("member");

      // And a draft vendor ...
      const createResponse = await member.post("/api/vendors", {
        data: {
          name: uniqueName("REV-01 Vendor"),
          category: "software",
          contact_email: "ap@rev01-vendor.example.com",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendor = await createResponse.json();
      expect(vendor.status).toBe("draft");

      // ... with extracted w9, insurance_certificate and contract documents
      const documentIds: string[] = [];
      for (const kind of KINDS) {
        const file = sampleFor(kind);
        const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
          multipart: {
            kind,
            file: {
              name: path.basename(file),
              mimeType: mimeTypeFor(file),
              buffer: fs.readFileSync(file),
            },
          },
        });
        expect(uploadResponse.status(), `upload ${kind}`).toBe(201);
        const document = await uploadResponse.json();
        expect(document.kind).toBe(kind);
        documentIds.push(document.id);
      }

      for (const documentId of documentIds) {
        await expect
          .poll(
            async () => {
              const res = await member.get(`/api/documents/${documentId}`);
              expect(res.status()).toBe(200);
              return (await res.json()).status;
            },
            { timeout: 90_000, intervals: [250, 500, 1000, 2000] },
          )
          .toBe("extracted");
      }

      // When I submit the vendor for review
      const submitResponse = await member.post(`/api/vendors/${vendor.id}/submit`);

      // Then the response status is 200
      expect(submitResponse.status()).toBe(200);

      // And the vendor status is "in_review"
      const submitted = await submitResponse.json();
      expect(submitted.id).toBe(vendor.id);
      expect(submitted.status).toBe("in_review");

      const fetched = await member.get(`/api/vendors/${vendor.id}`);
      expect(fetched.status()).toBe(200);
      expect((await fetched.json()).status).toBe("in_review");

      // And an audit event "vendor.submitted" is recorded
      const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
      expect(auditResponse.status()).toBe(200);
      const audit = await auditResponse.json();
      const submittedEvents = (audit.items as Array<{ action: string; actor: { email: string } }>).filter(
        (e) => e.action === "vendor.submitted",
      );
      expect(submittedEvents).toHaveLength(1);
      expect(submittedEvents[0].actor.email).toBe(USERS.member);
    },
  );
});
